    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint32(self);
  }

  @protected
  void sse_encode_u_64(BigInt self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putBigUint64(self);
  }

  @protected
  void sse_encode_u_8(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint8(self);
  }

  @protected
  void sse_encode_ui_prefs(UiPrefs self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_opt_String(self.themeMode, serializer);
    sse_encode_opt_box_autoadd_i_32(self.windowX, serializer);
    sse_encode_opt_box_autoadd_i_32(self.windowY, serializer);
    sse_encode_opt_box_autoadd_i_32(self.windowWidth, serializer);
    sse_encode_opt_box_autoadd_i_32(self.windowHeight, serializer);
    sse_encode_opt_String(self.lastVault, serializer);
    sse_encode_opt_box_autoadd_f_64(self.listPaneWidth, serializer);
  }

  @protected
  void sse_encode_unit(void self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
  }

  @protected
  void sse_encode_usize(BigInt self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putBigUint64(self);
  }

  @protected
  void sse_encode_vault_summary(VaultSummary self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.name, serializer);
    sse_encode_String(self.path, serializer);
    sse_encode_bool(self.hasKeyfile, serializer);
    sse_encode_bool(self.hasSync, serializer);
  }

  @protected
  void sse_encode_vault_tree(VaultTree self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_group_node(self.root, serializer);
    sse_encode_list_entry_summary(self.entries, serializer);
  }
}

